    /** What the accessors reach the locale engine through. */
    public interface Renderer {
        /**
         * The message with a key, rendered with its parameters.
         *
         * @param key the message's key
         * @param params its parameters, as the renderer's JSON takes them
         * @return the text
         */
        String render(String key, Map<String, Object> params);

        /**
         * A catalogued entity's forms in the current locale.
         *
         * @param key the entity's full key
         * @return its forms
         */
        EntityForms entity(String key);
    }

    /**
     * A catalogued entity's forms in the current locale.
     *
     * @param iast the `iast` form; empty when the record lacks it
     * @param name the `name` form; empty when the record lacks it
     * @param prose the `prose` form; empty when the record lacks it
     * @param short_ the `short` form, or null
     * @param glyph its glyph, or null
     * @param gender its grammatical gender, or null
     * @param forms every form the locale carries, including any a loaded pack brought
     */
    public record EntityForms(String iast, String name, String prose, String short_, String glyph, Gender gender, Map<String, String> forms) {
        /**
         * The forms as the boundary hands them out, parsed.
         *
         * @param raw the parsed JSON object
         * @return the forms
         * @throws IllegalArgumentException for JSON that is not an object
         */
        public static EntityForms of(Object raw) {
            if (!(raw instanceof Map<?, ?> forms)) {
                throw new IllegalArgumentException("an entity's forms are an object, not " + raw);
            }
            return new EntityForms(
                    text(forms, "iast", ""),
                    text(forms, "name", ""),
                    text(forms, "prose", ""),
                    text(forms, "short", null),
                    text(forms, "glyph", null),
                    gender(text(forms, "gender", null)),
                    all(forms));
        }

        private static String text(Map<?, ?> forms, String form, String absent) {
            return forms.get(form) instanceof String found ? found : absent;
        }

        private static Map<String, String> all(Map<?, ?> forms) {
            Map<String, String> found = new TreeMap<>();
            forms.forEach((name, value) -> {
                if (name instanceof String key && value instanceof String text) {
                    found.put(key, text);
                }
            });
            return Collections.unmodifiableMap(found);
        }

        private static Gender gender(String value) {
            for (Gender member : Gender.values()) {
                if (member.value().equals(value)) {
                    return member;
                }
            }
            return null;
        }
    }


